#!/usr/bin/env python3
import csv
import json
from pathlib import Path

CATALOG_PATH = Path('/root/therapy_catalog.json')
BAG_COST_PATH = Path('/root/bag_supply_cost.csv')
PAYMENT_PATH = Path('/root/delivery_payment.csv')
OVERRIDES_PATH = Path('/root/patient_overrides.csv')
ANALYSIS_OUT = Path('/root/infusion_batch_analysis.json')
SUMMARY_OUT = Path('/root/infusion_batch_summary.md')

DELIVERIES_7 = 52
DELIVERIES_14 = 26
DAYS_7 = 7
DAYS_14 = 14
THRESHOLD = 15000


def include_flag(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.strip().lower() in {'true', '1', 'yes', 'y'}
    return bool(value)


def flatten_therapies(catalog):
    if isinstance(catalog, list):
        return catalog
    if isinstance(catalog, dict):
        if isinstance(catalog.get('therapies'), list):
            return catalog['therapies']
        therapies = []
        for service_line in catalog.get('service_lines', []):
            therapies.extend(service_line.get('therapies', []))
        return therapies
    raise ValueError('Unsupported therapy catalog format')


def read_csv_rows(path):
    with path.open(newline='') as f:
        return list(csv.DictReader(f))


def to_float(value, field):
    try:
        return float(value)
    except (TypeError, ValueError):
        raise ValueError(f'Invalid numeric value for {field}: {value!r}')


def to_int(value, field):
    try:
        return int(float(value))
    except (TypeError, ValueError):
        raise ValueError(f'Invalid integer value for {field}: {value!r}')


def pick_patient_count_column(fieldnames):
    preferred = ['active_patients', 'patient_count', 'patients', 'active_patient_count']
    for name in preferred:
        if name in fieldnames:
            return name
    for name in fieldnames:
        lowered = name.lower()
        if 'patient' in lowered and ('count' in lowered or 'active' in lowered):
            return name
    raise ValueError(f'Could not identify patient count column from {fieldnames}')


def compute_model(therapy, active_patients, bag_cost, payment, days_per_delivery, deliveries_per_year):
    drug_cost = (
        therapy['drug_cost_per_1000_mg_usd']
        * active_patients
        * therapy['dose_mg_per_day']
        * days_per_delivery
        * deliveries_per_year
        / 1000
    )
    supply_cost = bag_cost * active_patients * deliveries_per_year
    revenue = payment * active_patients * deliveries_per_year
    margin = revenue - drug_cost - supply_cost
    return drug_cost, supply_cost, revenue, margin


def main():
    catalog = json.loads(CATALOG_PATH.read_text())
    all_therapies = flatten_therapies(catalog)
    in_scope = [t for t in all_therapies if include_flag(t.get('include_in_review'))]
    in_scope_by_code = {t['therapy_code']: t for t in in_scope}

    bag_cost_rows = read_csv_rows(BAG_COST_PATH)
    bag_cost_by_size = {
        to_int(row['bag_size_ml'], 'bag_size_ml'): to_float(row['bag_supply_cost_usd'], 'bag_supply_cost_usd')
        for row in bag_cost_rows
    }

    payment_rows = read_csv_rows(PAYMENT_PATH)
    labels_to_code = {}
    lower_labels_to_code = {}
    for therapy in in_scope:
        labels = [therapy.get('therapy_name', '')] + list(therapy.get('aliases') or [])
        for label in labels:
            if not label:
                continue
            labels_to_code[label] = therapy['therapy_code']
            lower_labels_to_code[label.lower()] = therapy['therapy_code']

    payment_by_code = {}
    unmatched_payment_labels = []
    for row in payment_rows:
        label = row['therapy_label']
        code = labels_to_code.get(label)
        if code is None:
            code = lower_labels_to_code.get(label.lower())
        if code is None:
            unmatched_payment_labels.append(label)
            continue
        payment_by_code[code] = to_float(row['payment_per_delivery_per_patient_usd'], 'payment_per_delivery_per_patient_usd')

    override_rows = read_csv_rows(OVERRIDES_PATH)
    if not override_rows:
        raise ValueError('patient_overrides.csv has no rows')
    patient_count_column = pick_patient_count_column(override_rows[0].keys())
    best_override_by_code = {}
    for row in override_rows:
        code = row.get('therapy_code')
        if code not in in_scope_by_code:
            continue
        if (row.get('status') or '').strip().lower() != 'approved':
            continue
        revision = to_int(row.get('revision'), 'revision')
        active_patients = to_int(row.get(patient_count_column), patient_count_column)
        current = best_override_by_code.get(code)
        if current is None or revision > current['revision']:
            best_override_by_code[code] = {'revision': revision, 'active_patients': active_patients}

    therapies_output = []
    for therapy in sorted(in_scope, key=lambda t: t['therapy_code']):
        code = therapy['therapy_code']
        if code not in best_override_by_code:
            raise ValueError(f'Missing approved patient override for in-scope therapy {code}')
        if code not in payment_by_code:
            raise ValueError(f'Missing delivery payment for in-scope therapy {code}')
        bag_size_ml = to_int(therapy['bag_size_ml'], 'bag_size_ml')
        if bag_size_ml not in bag_cost_by_size:
            raise ValueError(f'Missing bag supply cost for bag size {bag_size_ml} ml')

        normalized_therapy = {
            **therapy,
            'drug_cost_per_1000_mg_usd': to_float(therapy['drug_cost_per_1000_mg_usd'], 'drug_cost_per_1000_mg_usd'),
            'dose_mg_per_day': to_float(therapy['dose_mg_per_day'], 'dose_mg_per_day'),
            'bag_size_ml': bag_size_ml,
        }
        active_patients = best_override_by_code[code]['active_patients']
        bag_cost = bag_cost_by_size[bag_size_ml]
        payment = payment_by_code[code]

        drug7, supply7, revenue7, margin7 = compute_model(
            normalized_therapy, active_patients, bag_cost, payment, DAYS_7, DELIVERIES_7
        )
        drug14, supply14, revenue14, margin14 = compute_model(
            normalized_therapy, active_patients, bag_cost, payment, DAYS_14, DELIVERIES_14
        )
        diff = margin14 - margin7

        therapies_output.append({
            'therapy_code': code,
            'therapy_name': normalized_therapy.get('therapy_name'),
            'active_patients': active_patients,
            'bag_size_ml': bag_size_ml,
            'bag_supply_cost_usd': round(bag_cost, 2),
            'payment_per_delivery_per_patient_usd': round(payment, 2),
            'drug_cost_per_1000_mg_usd': round(normalized_therapy['drug_cost_per_1000_mg_usd'], 2),
            'dose_mg_per_day': normalized_therapy['dose_mg_per_day'],
            'annual_drug_cost_7_day_usd': round(drug7, 2),
            'annual_supply_cost_7_day_usd': round(supply7, 2),
            'annual_revenue_7_day_usd': round(revenue7, 2),
            'annual_margin_7_day_usd': round(margin7, 2),
            'annual_drug_cost_14_day_usd': round(drug14, 2),
            'annual_supply_cost_14_day_usd': round(supply14, 2),
            'annual_revenue_14_day_usd': round(revenue14, 2),
            'annual_margin_14_day_usd': round(margin14, 2),
            'annual_margin_difference_14_minus_7_usd': round(diff, 2),
        })

    total_margin_7 = round(sum(t['annual_margin_7_day_usd'] for t in therapies_output), 2)
    total_margin_14 = round(sum(t['annual_margin_14_day_usd'] for t in therapies_output), 2)
    total_diff = round(sum(t['annual_margin_difference_14_minus_7_usd'] for t in therapies_output), 2)
    abs_total_diff = round(abs(total_diff), 2)
    decision = 'move_to_14_day' if abs_total_diff < THRESHOLD else 'keep_7_day'

    result = {
        'assumptions': {
            'deliveries_per_year_7_day': DELIVERIES_7,
            'deliveries_per_year_14_day': DELIVERIES_14,
            'days_per_delivery_7_day': DAYS_7,
            'days_per_delivery_14_day': DAYS_14,
            'switch_threshold_usd': THRESHOLD,
            'patient_override_rule': 'highest approved revision per therapy_code',
        },
        'therapies': therapies_output,
        'totals': {
            'total_annual_margin_7_day_usd': total_margin_7,
            'total_annual_margin_14_day_usd': total_margin_14,
            'total_annual_margin_difference_14_minus_7_usd': total_diff,
            'absolute_total_margin_difference_usd': abs_total_diff,
        },
        'recommendation': {
            'decision': decision,
            'justification': (
                f'The absolute total margin difference is ${abs_total_diff:.2f}, '
                f'compared with the ${THRESHOLD:.2f} threshold, so the decision is {decision}.'
            ),
        },
    }

    with ANALYSIS_OUT.open('w') as f:
        json.dump(result, f, indent=2)
        f.write('\n')

    summary = [
        '# Infusion Batch Analysis Summary',
        '',
        f'- Total 7-day annual margin: ${total_margin_7:.2f} USD',
        f'- Total 14-day annual margin: ${total_margin_14:.2f} USD',
        f'- Absolute margin difference: ${abs_total_diff:.2f} USD',
        f'- Recommendation: {decision}',
    ]
    SUMMARY_OUT.write_text('\n'.join(summary) + '\n')


if __name__ == '__main__':
    main()

