import json, csv, math
from pathlib import Path
analysis=json.loads(Path('/root/infusion_batch_analysis.json').read_text())
errors=[]
# schema
for key in ['assumptions','therapies','totals','recommendation']:
    if key not in analysis:
        errors.append(f'missing top-level {key}')
# sorted and in-scope
codes=[t['therapy_code'] for t in analysis['therapies']]
if codes != sorted(codes):
    errors.append(f'codes not sorted: {codes}')
cat=json.loads(Path('/root/therapy_catalog.json').read_text())
in_scope=[]
for sl in cat['service_lines']:
    for t in sl['therapies']:
        if bool(t['include_in_review']):
            in_scope.append(t['therapy_code'])
if set(codes)!=set(in_scope):
    errors.append(f'codes {codes} != in_scope {sorted(in_scope)}')
# summary nonempty line count + required tokens
summary=Path('/root/infusion_batch_summary.md').read_text().splitlines()
nonempty=[line for line in summary if line.strip()]
if not (4 <= len(nonempty) <= 8):
    errors.append(f'summary nonempty line count {len(nonempty)}')
for text in ['Total 7-day annual margin','Total 14-day annual margin','Absolute margin difference', analysis['recommendation']['decision']]:
    if text not in '\n'.join(summary):
        errors.append(f'summary missing {text}')
# manual spot check first therapy
bag={int(r['bag_size_ml']):float(r['bag_supply_cost_usd']) for r in csv.DictReader(open('/root/bag_supply_cost.csv'))}
pay={r['therapy_label']:float(r['payment_per_delivery_per_patient_usd']) for r in csv.DictReader(open('/root/delivery_payment.csv'))}
rows=list(csv.DictReader(open('/root/patient_overrides.csv')))
first=analysis['therapies'][0]
raw=None
for sl in cat['service_lines']:
    for t in sl['therapies']:
        if t['therapy_code']==first['therapy_code']:
            raw=t
approved=[r for r in rows if r['therapy_code']==first['therapy_code'] and r['status'].lower()=='approved']
best=max(approved, key=lambda r:int(r['revision']))
active=int(best['active_patients'])
payment=None
for label in [raw['therapy_name']]+raw.get('aliases',[]):
    if label in pay:
        payment=pay[label]
        break
supply=bag[int(raw['bag_size_ml'])]
calc={}
for suffix, days, deliveries in [('7_day',7,52),('14_day',14,26)]:
    drug=raw['drug_cost_per_1000_mg_usd']*active*raw['dose_mg_per_day']*days*deliveries/1000
    sup=supply*active*deliveries
    rev=payment*active*deliveries
    mar=rev-drug-sup
    calc[f'annual_drug_cost_{suffix}_usd']=round(drug,2)
    calc[f'annual_supply_cost_{suffix}_usd']=round(sup,2)
    calc[f'annual_revenue_{suffix}_usd']=round(rev,2)
    calc[f'annual_margin_{suffix}_usd']=round(mar,2)
calc['annual_margin_difference_14_minus_7_usd']=round(calc['annual_margin_14_day_usd']-calc['annual_margin_7_day_usd'],2)
for k,v in calc.items():
    if first.get(k)!=v:
        errors.append(f'first therapy {k}: output {first.get(k)} != manual {v}')
# JSON dumpability already parsed
print('VALIDATION_ERRORS=' + repr(errors))
print('THERAPY_CODES=' + repr(codes))
print('FIRST_THERAPY=' + first['therapy_code'])
print('MANUAL_SPOT_CHECK=' + json.dumps(calc, sort_keys=True))
print('TOTALS=' + json.dumps(analysis['totals'], sort_keys=True))
print('DECISION=' + analysis['recommendation']['decision'])
